source = '''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    bands = []
    start = None
    for r in range(h + 1):
        occupied = r < h and any(v != bg for v in grid[r])
        if occupied and start is None:
            start = r
        elif not occupied and start is not None:
            bands.append((start, r))
            start = None
    if len(bands) != 2:
        return [row[:] for row in grid]
    (a0, a1), (b0, b1) = bands
    if a1 - a0 != b1 - b0:
        return [row[:] for row in grid]
    rows = a1 - a0
    # Find the horizontal offset that best aligns the two repeated patterns.
    candidates = []
    for dx in range(-(w - 1), w):
        overlap = 0
        mismatch = 0
        for dr in range(rows):
            for x in range(w):
                y = x - dx
                if 0 <= y < w:
                    overlap += 1
                    mismatch += ((grid[a0 + dr][x] != bg) != (grid[b0 + dr][y] != bg))
        candidates.append((mismatch, -overlap, abs(dx), dx))
    dx = min(candidates)[-1]
    ca = sum(v != bg for r in range(a0, a1) for v in grid[r])
    cb = sum(v != bg for r in range(b0, b1) for v in grid[r])
    target_is_a = ca <= cb
    out = [row[:] for row in grid]
    if target_is_a:
        # A[x] corresponds to B[x-dx], so map source B into A by +dx.
        for dr in range(rows):
            for xb in range(w):
                xa = xb + dx
                if 0 <= xa < w and grid[b0 + dr][xb] != bg and grid[a0 + dr][xa] == bg:
                    out[a0 + dr][xa] = 1
    else:
        # Map source A into B by -dx.
        for dr in range(rows):
            for xa in range(w):
                xb = xa - dx
                if 0 <= xb < w and grid[a0 + dr][xa] != bg and grid[b0 + dr][xb] == bg:
                    out[b0 + dr][xb] = 1
    return out
'''
